import { TsComboboxField, TsFieldOptions, TsWidgetProps } from "../types"
import { getFieldClasses, sanitizeId } from "../utils"

export type TsComboboxWidgetProps = TsWidgetProps<TsComboboxField>

export const ComboboxWidget = React.forwardRef<HTMLButtonElement, TsComboboxWidgetProps>(
  (
    {
      field,
      def,
      name,
      error,
      hint: _hint,
      readOnly,
      autoFocus,
      "aria-label": ariaLabel,
      "aria-required": ariaRequired,
      ...props
    },
    ref
  ) => {
    const [open, setOpen] = React.useState(false)
    const [searchValue, setSearchValue] = React.useState("")
    const safeId = sanitizeId(name)
    const tf = useTsLocale().strings.form
    const options = (def.options || []).map((opt: TsFieldOptions | string) => {
      const value = typeof opt === "string" ? opt : String(opt.value)
      const label = typeof opt === "string" ? opt : opt.label
      return { value, label }
    })

    // Allow custom value if not found (exact match)
    const showCustom =
      def.allowCustom &&
      searchValue &&
      !options.find((o) => o.label.toLowerCase() === searchValue.toLowerCase())

    const { errorClass, readonlyClass, readonlyPointerClass } = getFieldClasses(error, readOnly)

    return (
      <Popover
        open={readOnly ? false : open}
        onOpenChange={(v) => {
          if (!readOnly && !def.disabled) setOpen(v)
        }}
      >
        <PopoverTrigger asChild>
          <div className="relative group/combobox w-full">
            <Button
              id={safeId}
              type="button"
              variant="outline"
              role="combobox"
              aria-expanded={open}
              aria-invalid={!!error}
              aria-label={ariaLabel}
              aria-required={ariaRequired}
              aria-readonly={readOnly}
              aria-controls={`popover-content-${safeId}`}
              autoFocus={autoFocus}
              tabIndex={readOnly ? -1 : undefined}
              className={cn(
                "w-full justify-between hover:bg-background dark:hover:bg-input/30 pr-8",
                errorClass,
                readonlyClass,
                readonlyPointerClass,
                readOnly && "opacity-100 pointer-events-none pr-3"
              )}
              disabled={def.disabled}
              {...props}
              ref={ref || (field.ref as React.Ref<HTMLButtonElement>)}
            >
              <span className="truncate">
                {field.value
                  ? (options.find((framework) => framework.value === field.value)?.label ??
                    (field.value as string))
                  : def.placeholder || tf.selectPlaceholder}
              </span>
              <ChevronsUpDown
                className={cn("ml-2 h-4 w-4 shrink-0 opacity-50", readOnly && "hidden")}
              />
            </Button>
            {!readOnly && !def.disabled && def.clearable && field.value && (
              <button
                type="button"
                className="absolute right-8 top-1/2 -translate-y-1/2 p-1 text-muted-foreground hover:text-foreground opacity-0 group-hover/combobox:opacity-100 transition-opacity"
                onClick={(e) => {
                  e.preventDefault()
                  e.stopPropagation()
                  field.onChange("")
                  setOpen(false)
                }}
              >
                <X className="h-3 w-3" />
              </button>
            )}
          </div>
        </PopoverTrigger>
        <PopoverContent
          id={`popover-content-${safeId}`}
          className="w-full p-0"
          onOpenAutoFocus={(e) => {
            e.preventDefault()
            ;(e.currentTarget as HTMLElement).querySelector("input")?.focus()
          }}
          onEscapeKeyDown={(e) => {
            if (searchValue) {
              e.preventDefault()
              setSearchValue("")
            }
          }}
        >
          <Command
            filter={(value, search) => (value.toLowerCase().includes(search.toLowerCase()) ? 1 : 0)}
          >
            <CommandInput
              placeholder={def.placeholder || tf.searchPlaceholder}
              value={searchValue}
              onValueChange={setSearchValue}
            />
            <CommandList>
              <CommandEmpty className="py-1.5 px-2 text-left">
                <span className="italic text-muted-foreground text-sm">
                  {def.notFoundMessage || tf.notFound}
                </span>
              </CommandEmpty>
              <CommandGroup>
                {options.map((framework) => (
                  <CommandItem
                    key={framework.value}
                    value={framework.label}
                    onSelect={(currentValue: string) => {
                      const original = options.find(
                        (o) => o.label.toLowerCase() === currentValue.toLowerCase()
                      )
                      field.onChange(original ? original.value : currentValue)
                      setSearchValue("")
                      setOpen(false)
                    }}
                  >
                    <Check
                      className={cn(
                        "mr-2 h-4 w-4",
                        field.value === framework.value ? "opacity-100" : "opacity-0"
                      )}
                    />
                    {framework.label}
                  </CommandItem>
                ))}
                {showCustom && (
                  <CommandItem
                    value={`\x00custom:${searchValue}`}
                    onSelect={() => {
                      field.onChange(searchValue)
                      setSearchValue("")
                      setOpen(false)
                    }}
                  >
                    <Check className="mr-2 h-4 w-4 opacity-0" />
                    {tf.customValueAdd(searchValue)}
                  </CommandItem>
                )}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    )
  }
)
ComboboxWidget.displayName = "ComboboxWidget"

"use client"

import { format, isValid as isValidDate } from "date-fns"
import { CalendarIcon } from "lucide-react"

import * as React from "react"
import type { Matcher } from "react-day-picker"
import { useTsLocale } from "@/components/ts-web-ui/locale"
import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"

import { cn } from "@/lib/utils"

import { TsDateField, TsWidgetProps } from "../types"
import {
  getDateLocale,
  getFieldClasses,
  handleFieldKeyDown,
  isDateWithinBounds,
  parseSmartDate,
  resolveMaxDateBound,
  resolveMinDateBound,
  sanitizeId,
} from "../utils"

export type TsDateWidgetProps = TsWidgetProps<TsDateField>

function toDateOnlyString(date: Date): string {
  return format(date, "yyyy-MM-dd")
}

function parseDateValue(value: unknown): Date | undefined {
  if (!value) return undefined

  if (value instanceof Date) {
    return isNaN(value.getTime()) ? undefined : value
  }

  if (typeof value === "string") {
    const trimmed = value.trim()

    // Preferred storage for date-only fields.
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(trimmed)
    if (m) {
      const y = Number(m[1])
      const mo = Number(m[2])
      const d = Number(m[3])
      const localDate = new Date(y, mo - 1, d)
      return isNaN(localDate.getTime()) ? undefined : localDate
    }

    const parsed = new Date(trimmed)
    return isNaN(parsed.getTime()) ? undefined : parsed
  }

  if (typeof value === "number") {
    const parsed = new Date(value)
    return isNaN(parsed.getTime()) ? undefined : parsed
  }

  return undefined
}

export const DateWidget = React.forwardRef<HTMLInputElement, TsDateWidgetProps>(
  (
    {
      field,
      def,
      error,
      hint: _hint,
      name,
      readOnly,
      autoFocus,
      "aria-label": ariaLabel,
      "aria-required": ariaRequired,
      ...props
    },
    ref
  ) => {
    const [open, setOpen] = React.useState(false)
    const [isFocused, setIsFocused] = React.useState(false)
    const safeId = sanitizeId(name)
    const tf = useTsLocale().strings.form

    const { errorClass, readonlyClass, readonlyPointerClass } = getFieldClasses(error, readOnly)

    const dateFormat = def.dateFormat || "d.M.yyyy"
    const [inputValue, setInputValue] = React.useState(() => {
      const validDate = parseDateValue(field.value)
      return validDate ? format(validDate, dateFormat) : ""
    })

    // Compute calendar date from inputValue first, then field.value as fallback
    const calendarDate = React.useMemo(() => {
      if (inputValue.trim()) {
        const parsed = parseSmartDate(inputValue)
        if (parsed) return parsed
      }
      return parseDateValue(field.value)
    }, [inputValue, field.value])

    // Only sync input from field value when not focused
    React.useEffect(() => {
      if (isFocused) return
      if (!field.value) {
        setInputValue("")
        return
      }
      const validDate = parseDateValue(field.value)
      if (validDate && !open) {
        setInputValue(format(validDate, dateFormat))
      }
    }, [field.value, dateFormat, open, isFocused])

    // Get date-fns locale object from string
    const dateLocale = React.useMemo(() => getDateLocale(def.locale), [def.locale])

    // Upper/lower date bounds. disableFuture and maxDate combine (the earlier wins); date-only
    // bounds are parsed in local time so they match the calendar's local-midnight days.
    const maxBound = React.useMemo(
      () => resolveMaxDateBound({ disableFuture: def.disableFuture, maxDate: def.maxDate }),
      [def.disableFuture, def.maxDate]
    )

    const minBound = React.useMemo(() => resolveMinDateBound(def.minDate), [def.minDate])

    const disabledMatcher = React.useMemo<Matcher[] | undefined>(() => {
      const matchers: Matcher[] = []
      if (maxBound) matchers.push({ after: maxBound })
      if (minBound) matchers.push({ before: minBound })
      return matchers.length > 0 ? matchers : undefined
    }, [maxBound, minBound])

    const isDateAllowed = React.useCallback(
      (date: Date) => isDateWithinBounds(date, minBound, maxBound),
      [minBound, maxBound]
    )
    const isTodayAllowed = isDateAllowed(new Date())

    const resetInputFromField = React.useCallback(() => {
      const dv = field.value ? new Date(field.value as string | number | Date) : undefined
      setInputValue(dv && !isNaN(dv.getTime()) ? format(dv, dateFormat) : "")
    }, [field.value, dateFormat])

    const handleInputBlur = () => {
      setIsFocused(false)
      const trimmed = inputValue.trim()
      if (!trimmed) {
        if (field.value) field.onChange(null)
        return
      }

      const parsed = parseSmartDate(trimmed)

      if (parsed && isValidDate(parsed) && isDateAllowed(parsed)) {
        field.onChange(toDateOnlyString(parsed))
        setInputValue(format(parsed, dateFormat))
      } else {
        // Out-of-range or invalid manual entry: revert to the last valid value.
        resetInputFromField()
      }
    }

    return (
      <Popover open={open} onOpenChange={readOnly || def.disabled ? undefined : setOpen}>
        <div className={cn("relative", readOnly && "pointer-events-none")}>
          <Input
            id={safeId}
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onFocus={(e) => {
              if (readOnly) return
              setIsFocused(true)
              if (def.selectAllOnFocus !== false) {
                const el = e.currentTarget
                setTimeout(() => el.select(), 0)
              }
            }}
            onClick={(e) => {
              if (
                def.selectAllOnFocus !== false &&
                !readOnly &&
                document.activeElement !== e.currentTarget
              ) {
                e.currentTarget.select()
              }
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                const parsed = parseSmartDate(inputValue)

                if (parsed && isValidDate(parsed) && isDateAllowed(parsed)) {
                  field.onChange(toDateOnlyString(parsed))
                  setInputValue(format(parsed, dateFormat))

                  // If it was a manual entry, stop propagation to prevent form action
                  // unless it's the exact same as current field value
                  const wasNew = !field.value || toDateOnlyString(parsed) !== String(field.value)
                  if (wasNew) {
                    e.preventDefault()
                    e.stopPropagation()
                    return
                  }
                } else if (parsed && isValidDate(parsed) && !isDateAllowed(parsed)) {
                  // Reject out-of-range manual entry.
                  e.preventDefault()
                  e.stopPropagation()
                  resetInputFromField()
                  return
                }
              }
              handleFieldKeyDown(
                e,
                name,
                def.enterAction,
                def.escapeAction,
                () => {
                  setInputValue("")
                  field.onChange(undefined)
                },
                field.value
              )
            }}
            onBlur={handleInputBlur}
            placeholder={def.placeholder || dateFormat.toLowerCase()}
            disabled={def.disabled}
            readOnly={readOnly}
            autoFocus={autoFocus}
            tabIndex={readOnly ? -1 : undefined}
            aria-invalid={!!error}
            aria-readonly={readOnly}
            aria-label={ariaLabel}
            aria-required={ariaRequired}
            className={cn("pr-10 text-right", errorClass, readonlyClass, readonlyPointerClass)}
            {...props}
            ref={ref || field.ref}
          />
          <PopoverTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className={cn(
                "absolute right-0 top-0 h-full w-9 rounded-l-none text-muted-foreground hover:text-foreground",
                (readOnly || def.disabled) && "pointer-events-none"
              )}
              disabled={def.disabled}
              type="button"
            >
              <CalendarIcon className="h-4 w-4" />
            </Button>
          </PopoverTrigger>
        </div>
        <PopoverContent className="w-auto p-0" align="start">
          <Calendar
            mode="single"
            selected={calendarDate}
            defaultMonth={calendarDate}
            locale={dateLocale}
            disabled={disabledMatcher}
            onSelect={(date) => {
              if (date && isDateAllowed(date)) {
                field.onChange(toDateOnlyString(date))
                setInputValue(format(date, dateFormat))
              }
              setOpen(false)
            }}
            autoFocus
          />
          {(def.showTodayButton !== false || def.showClearButton !== false) && (
            <div className="flex items-center justify-between p-2 border-t gap-2 bg-muted/10">
              {def.showClearButton !== false && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-xs h-8 px-2 flex-1"
                  onClick={() => {
                    field.onChange(null)
                    setInputValue("")
                    setOpen(false)
                  }}
                >
                  {def.clearButtonText || tf.clear}
                </Button>
              )}
              {def.showTodayButton !== false && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-xs h-8 px-2 flex-1"
                  disabled={!isTodayAllowed}
                  onClick={() => {
                    const today = new Date()
                    if (!isDateAllowed(today)) return
                    field.onChange(toDateOnlyString(today))
                    setInputValue(format(today, dateFormat))
                    setOpen(false)
                  }}
                >
                  {def.todayButtonText || tf.today}
                </Button>
              )}
            </div>
          )}
        </PopoverContent>
      </Popover>
    )
  }
)
DateWidget.displayName = "DateWidget"

"use client"

import { format, isValid as isValidDate } from "date-fns"
import { CalendarIcon } from "lucide-react"

import * as React from "react"
import type { Matcher } from "react-day-picker"
import { useTsLocale } from "@/components/ts-web-ui/locale"
import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"

import { cn } from "@/lib/utils"

import { TsDateTimeField, TsWidgetProps } from "../types"
import {
  getDateLocale,
  getFieldClasses,
  handleFieldKeyDown,
  isDateWithinBounds,
  parseSmartDateTime,
  resolveMaxDateBound,
  resolveMinDateBound,
  sanitizeId,
} from "../utils"

export type TsDateTimeWidgetProps = TsWidgetProps<TsDateTimeField>

export const DateTimeWidget = React.forwardRef<HTMLInputElement, TsDateTimeWidgetProps>(
  (
    {
      field,
      def,
      error,
      hint: _hint,
      name,
      readOnly,
      autoFocus,
      "aria-label": ariaLabel,
      "aria-required": ariaRequired,
      ...props
    },
    ref
  ) => {
    const [open, setOpen] = React.useState(false)
    const [isFocused, setIsFocused] = React.useState(false)
    const safeId = sanitizeId(name)
    const tf = useTsLocale().strings.form

    const { errorClass, readonlyClass, readonlyPointerClass } = getFieldClasses(error, readOnly)

    const dateFormat = def.dateFormat || "d.M.yyyy HH:mm"
    const [inputValue, setInputValue] = React.useState(() => {
      const dateValue = field.value ? new Date(field.value as string | number | Date) : undefined
      const validDate = dateValue && !isNaN(dateValue.getTime()) ? dateValue : undefined
      return validDate ? format(validDate, dateFormat) : ""
    })

    // Only sync input from field value when not focused
    React.useEffect(() => {
      if (isFocused) return
      if (!field.value) {
        setInputValue("")
        return
      }
      const dateValue = new Date(field.value as string | number | Date)
      const validDate = !isNaN(dateValue.getTime()) ? dateValue : undefined
      if (validDate && !open) {
        setInputValue(format(validDate, dateFormat))
      }
    }, [field.value, dateFormat, open, isFocused])

    // Get date-fns locale object from string
    const dateLocale = React.useMemo(() => getDateLocale(def.locale), [def.locale])

    // Upper/lower date bounds. disableFuture and maxDate combine (the earlier wins); date-only
    // bounds are parsed in local time so they match the calendar's local-midnight days.
    const maxBound = React.useMemo(
      () => resolveMaxDateBound({ disableFuture: def.disableFuture, maxDate: def.maxDate }),
      [def.disableFuture, def.maxDate]
    )

    const minBound = React.useMemo(() => resolveMinDateBound(def.minDate), [def.minDate])

    const disabledMatcher = React.useMemo<Matcher[] | undefined>(() => {
      const matchers: Matcher[] = []
      if (maxBound) matchers.push({ after: maxBound })
      if (minBound) matchers.push({ before: minBound })
      return matchers.length > 0 ? matchers : undefined
    }, [maxBound, minBound])

    const isDateAllowed = React.useCallback(
      (date: Date) => isDateWithinBounds(date, minBound, maxBound),
      [minBound, maxBound]
    )
    const isTodayAllowed = isDateAllowed(new Date())

    const getValidDate = () => {
      const dateValue = field.value ? new Date(field.value as string | number | Date) : undefined
      return dateValue && !isNaN(dateValue.getTime()) ? dateValue : undefined
    }

    const getTimeValue = () => {
      const vd = getValidDate()
      return vd
        ? `${String(vd.getHours()).padStart(2, "0")}:${String(vd.getMinutes()).padStart(2, "0")}`
        : ""
    }

    const resetInputFromField = React.useCallback(() => {
      const dv = field.value ? new Date(field.value as string | number | Date) : undefined
      setInputValue(dv && !isNaN(dv.getTime()) ? format(dv, dateFormat) : "")
    }, [field.value, dateFormat])

    const handleDateSelect = (date: Date | undefined) => {
      if (readOnly) return
      if (!date) {
        field.onChange(undefined)
        return
      }
      if (!isDateAllowed(date)) return
      const newDate = new Date(date)
      const vd = getValidDate()
      if (vd) {
        newDate.setHours(vd.getHours(), vd.getMinutes(), 0, 0)
      }
      field.onChange(newDate)
    }

    const handleTimeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (readOnly) return
      const parts = e.target.value.split(":")
      const hours = parseInt(parts[0] || "0")
      const minutes = parseInt(parts[1] || "0")
      const newDate = getValidDate() ? new Date(getValidDate()!) : new Date()
      newDate.setHours(hours, minutes, 0, 0)
      field.onChange(newDate)
    }

    const handleInputBlur = () => {
      setIsFocused(false)
      const trimmed = inputValue.trim()
      if (!trimmed) {
        if (field.value) field.onChange(null)
        return
      }

      const parsed = parseSmartDateTime(trimmed)

      if (parsed && isValidDate(parsed) && isDateAllowed(parsed)) {
        field.onChange(parsed)
        setInputValue(format(parsed, dateFormat))
      } else {
        resetInputFromField()
      }
    }

    return (
      <Popover open={open} onOpenChange={readOnly || def.disabled ? undefined : setOpen}>
        <div className={cn("relative", readOnly && "pointer-events-none")}>
          <Input
            id={safeId}
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onFocus={(e) => {
              if (readOnly) return
              setIsFocused(true)
              if (def.selectAllOnFocus !== false) {
                const el = e.currentTarget
                setTimeout(() => el.select(), 0)
              }
            }}
            onClick={(e) => {
              if (
                def.selectAllOnFocus !== false &&
                !readOnly &&
                document.activeElement !== e.currentTarget
              ) {
                e.currentTarget.select()
              }
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                const parsed = parseSmartDateTime(inputValue)

                if (parsed && isValidDate(parsed) && isDateAllowed(parsed)) {
                  field.onChange(parsed)
                  setInputValue(format(parsed, dateFormat))

                  const wasNew =
                    !field.value || new Date(field.value as string).getTime() !== parsed.getTime()
                  if (wasNew) {
                    e.preventDefault()
                    e.stopPropagation()
                    return
                  }
                } else if (parsed && isValidDate(parsed) && !isDateAllowed(parsed)) {
                  e.preventDefault()
                  e.stopPropagation()
                  resetInputFromField()
                  return
                }
              }
              handleFieldKeyDown(
                e,
                name,
                def.enterAction,
                def.escapeAction,
                () => {
                  setInputValue("")
                  field.onChange(undefined)
                },
                field.value
              )
            }}
            onBlur={handleInputBlur}
            placeholder={def.placeholder || dateFormat.toLowerCase()}
            disabled={def.disabled}
            readOnly={readOnly}
            autoFocus={autoFocus}
            tabIndex={readOnly ? -1 : undefined}
            aria-invalid={!!error}
            aria-readonly={readOnly}
            aria-label={ariaLabel}
            aria-required={ariaRequired}
            className={cn("pr-10 text-right", errorClass, readonlyClass, readonlyPointerClass)}
            {...props}
            ref={ref || field.ref}
          />
          <PopoverTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className={cn(
                "absolute right-0 top-0 h-full w-9 rounded-l-none text-muted-foreground hover:text-foreground",
                (readOnly || def.disabled) && "pointer-events-none"
              )}
              disabled={def.disabled}
              type="button"
            >
              <CalendarIcon className="h-4 w-4" />
            </Button>
          </PopoverTrigger>
        </div>
        <PopoverContent className="w-auto p-0" align="start">
          <Calendar
            mode="single"
            selected={getValidDate()}
            onSelect={handleDateSelect}
            locale={dateLocale}
            disabled={disabledMatcher}
            autoFocus
          />
          {(def.showTodayButton !== false || def.showClearButton !== false) && (
            <div className="flex items-center justify-between p-2 border-t gap-2 bg-muted/10 px-3">
              {def.showClearButton !== false && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-xs h-8 px-2 flex-1"
                  onClick={() => {
                    field.onChange(null)
                    setInputValue("")
                    setOpen(false)
                  }}
                >
                  {def.clearButtonText || tf.clear}
                </Button>
              )}
              {def.showTodayButton !== false && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-xs h-8 px-2 flex-1"
                  disabled={!isTodayAllowed}
                  onClick={() => {
                    const today = new Date()
                    if (!isDateAllowed(today)) return
                    field.onChange(today)
                    setInputValue(format(today, dateFormat))
                    setOpen(false)
                  }}
                >
                  {def.todayButtonText || tf.today}
                </Button>
              )}
            </div>
          )}
          <div className="border-t p-3 space-y-3">
            <div className="flex items-center gap-2">
              <span className="text-sm text-muted-foreground w-10">{tf.time}</span>
              <Input
                type="time"
                value={getTimeValue()}
                onChange={handleTimeChange}
                className="h-8 text-sm text-right"
                disabled={readOnly || def.disabled}
                aria-label="Time"
              />
            </div>
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="w-full h-8 text-xs"
              onClick={() => setOpen(false)}
            >
              {tf.close}
            </Button>
          </div>
        </PopoverContent>
      </Popover>
    )
  }
)
DateTimeWidget.displayName = "DateTimeWidget"

"use client"

import * as React from "react"

import { TsEmptyField, TsWidgetProps } from "../types"

export type TsEmptyWidgetProps = TsWidgetProps<TsEmptyField>

export const EmptyWidget = React.forwardRef<HTMLDivElement, TsEmptyWidgetProps>(
  (
    {
      field: _field,
      def: _def,
      name: _name,
