"use client"

import * as React from "react"

import { Slider } from "@/components/ui/slider"

import { cn } from "@/lib/utils"

import { TsSliderField, TsWidgetProps } from "../types"

export type TsSliderWidgetProps = TsWidgetProps<TsSliderField>

export const SliderWidget = React.forwardRef<HTMLDivElement, TsSliderWidgetProps>(
  (
    {
      field,
      def,
      name: _name,
      error,
      hint: _hint,
      readOnly,
      autoFocus: _autoFocus,
      "aria-label": ariaLabel,
      "aria-required": ariaRequired,
      ...props
    },
    ref
  ) => {
    const [showTooltip, setShowTooltip] = React.useState(false)
    const [localValue, setLocalValue] = React.useState<number>(field.value ?? def.min ?? 0)
    const lastCommittedValueRef = React.useRef<number | undefined>(
      field.value as number | undefined
    )
    const previousFieldValueRef = React.useRef<number | undefined>(
      field.value as number | undefined
    )

    React.useEffect(() => {
      const currentFieldValue =
        field.value === null ? undefined : (field.value as number | undefined)
      const hasFormValueChanged =
        JSON.stringify(currentFieldValue) !== JSON.stringify(previousFieldValueRef.current)

      if (hasFormValueChanged) {
        const isExternalChange =
          JSON.stringify(currentFieldValue) !== JSON.stringify(lastCommittedValueRef.current)

        if (isExternalChange) {
          setLocalValue(currentFieldValue ?? def.min ?? 0)
        }

        previousFieldValueRef.current = currentFieldValue
        lastCommittedValueRef.current = currentFieldValue
      }
    }, [field.value, def.min])

    const min = def.min ?? 0
    const max = def.max ?? 100
    const percent =
      max !== min ? Math.min(100, Math.max(0, ((localValue - min) / (max - min)) * 100)) : 0

    return (
      <div
        className={cn("relative py-2")}
        {...props}
        ref={ref}
        onPointerEnter={() => setShowTooltip(true)}
        onPointerLeave={() => setShowTooltip(false)}
      >
        {showTooltip && (
          <div
            className="absolute -top-7 -translate-x-1/2 pointer-events-none whitespace-nowrap rounded-md border bg-popover text-popover-foreground px-2 py-0.5 text-xs shadow-md z-50"
            style={{ left: `${percent}%` }}
          >
            {localValue}
          </div>
        )}
        <Slider
          value={[localValue]}
          max={max}
          min={min}
          step={def.step || 1}
          onValueChange={(vals: number[]) => {
            if (readOnly) return
            setLocalValue(vals[0])
            setShowTooltip(true)
          }}
          onValueCommit={(vals: number[]) => {
            if (readOnly) return
            const val = vals[0]
            lastCommittedValueRef.current = val
            field.onChange(val)
            setTimeout(() => setShowTooltip(false), 300)
          }}
          disabled={def.disabled}
          aria-invalid={!!error}
          aria-label={ariaLabel || def.label}
          aria-required={ariaRequired}
          aria-readonly={readOnly}
          className={cn(
            error && "**:[[role=slider]]:border-destructive **:[[role=slider]]:bg-destructive",
            readOnly && "pointer-events-none opacity-100"
          )}
        />
      </div>
    )
  }
)
SliderWidget.displayName = "SliderWidget"

